<script setup lang="ts">import {computed,onMounted} from 'vue';import {useResearch} from '../stores/research';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import ModelSummary from '../components/ModelSummary.vue';import ImportancePlot from '../components/ImportancePlot.vue';import RunTable from '../components/RunTable.vue';const lab=useResearch(),{error,perform}=useTask();const latest=computed(()=>lab.runs.find(r=>r.status==='completed')),dataset=computed(()=>lab.datasets.find(d=>d.id===latest.value?.dataset_id)||lab.datasets[0]),findings=computed(()=>lab.findings.filter(f=>f.run_id===latest.value?.id)),buildings=computed(()=>[...(dataset.value?.train_buildings||[]),...(dataset.value?.test_buildings||[])].sort());onMounted(()=>perform(lab.load));</script><template><PageHeading index="01" title="把能耗关系，放到未见楼宇上检验" text="分组验证选模型，封存评估看泛化，重复置换读依赖。"><RouterLink class="outline" to="/models">建立分组研究 +</RouterLink></PageHeading><ErrorNotice :message="error" @retry="perform(lab.load)"/><section class="overview-blueprint"><div class="research-intent"><p class="eyebrow">RESEARCH POSITION</p><h2>楼宇不同，<br>模型还解释得通吗？</h2><p>同一栋楼的记录留在同一侧。<br>把没见过的楼宇留下，<br>让泛化评估与选模过程分开。</p><div class="split-diagram"><span><b>{{dataset?.train_buildings.length||'—'}}</b>栋训练</span><i>→</i><span><b>3</b>折分组验证</span><i>→</i><span><b>{{dataset?.test_buildings.length||'—'}}</b>栋封存</span></div><div class="building-groups"><span v-for="code in buildings" :key="code" :class="{sealed:dataset?.test_buildings.includes(code)}"><b>{{code}}</b><small>{{dataset?.test_buildings.includes(code)?'封存楼宇':'训练楼宇'}}</small></span></div><p class="diagram-note">{{dataset?.evaluation_released?'评估已公开，特征与候选配置保持锁定。':'封存楼宇目标尚未公开，首次提交会锁定选模配置。'}}</p></div><ModelSummary v-if="latest" :run="latest"/><section v-else class="first-study"><p class="eyebrow">BEFORE FINAL EVALUATION</p><h2>先完成一次<br>分组模型比较。</h2><p>数据已按楼宇准备。选择特征与候选范围后，训练任务会先锁定方案，再读取封存评估。</p><RouterLink to="/models">建立第一份研究 →</RouterLink></section></section><div class="overview-explanation"><ImportancePlot :findings="findings"/><aside class="paper-margin"><p class="eyebrow">FIELD NOTE / 01</p><h2>解释是一条线索，<br>还不是一项改造。</h2><p>建筑面积与设备装机可能共同变化，模型会在相关特征之间分配系数。置换也可能打破现实中成立的特征关系。</p><p>先核对运行排程与计量边界，再把模型依赖写成可现场验证的假设。</p><RouterLink to="/hypotheses">查看改造假设 ↗</RouterLink></aside></div><section class="run-directory"><div class="section-heading"><h2>研究记录</h2><span>同一数据集公开评估后只可同配置复算</span></div><RunTable :runs="lab.runs.slice(0,3)"/></section></template>
